func normalizeWhiteSpaceReplace(s string) string {
	var b strings.Builder
	b.Grow(len(s))
	for _, r := range s {
		if r == '\t' || r == '\n' || r == '\r' {
			b.WriteByte(' ')
		} else {
			b.WriteRune(r)
		}
	}
	return b.String()
}

func normalizeWhiteSpaceCollapse(s string) string {
	return strings.Join(strings.Fields(s), " ")
}
